Subroutine identidad<T>(valor As T) As T
  Return valor;
EndSubroutine
Algorithm Identidad
  Write identidad(4);
  Write identidad(2.5);
  Write identidad("hola");
EndAlgorithm

Record Caja<T>
  Define contenido As T;
EndRecord
Subroutine abrir<T>(c As Caja<T>) As T
  Return c.contenido;
EndSubroutine
Algorithm Cajas
  Define numeros As Caja<Integer> <- Caja(7);
  Write abrir(numeros), " ", abrir(Caja("x"));
EndAlgorithm

Subroutine mayor<T>(a As T, b As T) As T
  If a > b Then
    Return a;
  EndIf
  Return b;
EndSubroutine
Algorithm Mayor
  Write mayor(1, 2);
EndAlgorithm
